'use strict';
const STORAGE_KEY='jp-invitation-guests-v1', SETTINGS_KEY='jp-invitation-settings-v1';
const $=id=>document.getElementById(id);
const escapeHTML=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=id=>`<svg aria-hidden="true"><use href="#i-${id}"/></svg>`;
let guests=[],settings={},editId=null,deleteId=null,toastTimer,previewMode=false,animationTimers=[],animationBusy=false,storageOK=true;
try{const value=JSON.parse(localStorage.getItem(STORAGE_KEY)||'[]');if(Array.isArray(value))guests=value.filter(g=>g&&typeof g.id==='string'&&typeof g.name==='string').map(g=>({...g,phone:String(g.phone||''),email:String(g.email||''),channel:['email','sms','whatsapp'].includes(g.channel)?g.channel:'whatsapp',sent:g.sent===true}));settings=JSON.parse(localStorage.getItem(SETTINGS_KEY)||'{}')||{};}catch{storageOK=false;}
function toast(message){$('toast').textContent=message;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),4500);}
function persist(){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(guests));return true;}catch{toast('Browser storage is unavailable or full. Export your guest list now to keep a backup.');return false;}}
function newId(){return globalThis.crypto?.randomUUID?.()||`${Date.now()}-${Math.random().toString(36).slice(2)}`;}
function normalizePhone(value){const raw=String(value||'').trim();if(!raw)return '';if(!/^[+\d\s().-]+$/.test(raw))throw new Error('Use digits and a country code for the mobile number.');let digits=raw.replace(/\D/g,'');if(digits.startsWith('00'))digits=digits.slice(2);if(digits.startsWith('0')&&!raw.startsWith('+'))throw new Error('Add the country code: for example, +94771234567 instead of 0771234567.');if(!/^[1-9]\d{6,14}$/.test(digits))throw new Error('Enter a valid international mobile number, including country code.');return '+'+digits;}
function validateGuest(input){const name=String(input.name||'').trim(),email=String(input.email||'').trim(),phone=normalizePhone(input.phone);let channel=String(input.channel||'whatsapp').trim().toLowerCase();if(!name||name.length>100)throw new Error('Enter an invitation name of 1–100 characters.');if(email&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email))throw new Error('Enter a valid email address.');if(!phone&&!email)throw new Error('Add a mobile number or email address.');if(!['whatsapp','email','sms'].includes(channel))throw new Error('Preferred channel must be whatsapp, email or sms.');if(channel==='email'&&!email)throw new Error('Add an email address for email sharing.');if(channel!=='email'&&!phone){if(email)channel='email';else throw new Error('Add a mobile number for WhatsApp or SMS.');}return {name,phone,email,channel};}
function currentBase(){const url=new URL(location.href);url.hash='';url.search='';return url.href;}
function invitationURL(guest){const url=new URL(settings.baseURL||currentBase());url.search='';url.hash='invite='+encodeURIComponent(guest.name);return url.href;}
function isLocal(url){return ['localhost','127.0.0.1','terminal.local'].includes(url.hostname)||url.protocol==='file:';}
function checkSharingBase(){let url;try{url=new URL(settings.baseURL||currentBase());}catch{openSettings();return false;}if(isLocal(url)||url.hostname.endsWith('.chatgpt.site')){toast('Set your public Vercel website address before sharing guest links.');openSettings();return false;}return true;}
function messageFor(g){return `Dear ${g.name},\n\nWith love, we invite you to celebrate the wedding of Jihani & Pasindu on 27 January 2027 at Cinnamon Lakeside Hotel, Colombo.\n\nOpen your personal invitation:\n${invitationURL(g)}\n\nWe would love to celebrate with you!`;}
function composeURL(g,channel){const msg=encodeURIComponent(messageFor(g));if(channel==='whatsapp')return `https://wa.me/${g.phone.replace(/\D/g,'')}?text=${msg}`;if(channel==='email')return `mailto:${g.email}?subject=${encodeURIComponent('You are invited · Jihani & Pasindu')}&body=${msg}`;const apple=/iPhone|iPad|iPod/.test(navigator.userAgent);return `sms:${g.phone}${apple?'&':'?'}body=${msg}`;}
function render(){const q=$('search').value.trim().toLowerCase(),filter=$('filter').value;const visible=guests.filter(g=>(!q||`${g.name} ${g.phone} ${g.email}`.toLowerCase().includes(q))&&(filter==='all'||(filter==='sent'?g.sent:!g.sent)));$('total-count').textContent=guests.length;$('nav-count').textContent=guests.length;$('link-count').textContent=guests.length;$('list-count').textContent=guests.length;$('shared-count').textContent=guests.filter(g=>g.sent).length;$('empty-state').hidden=guests.length>0;$('guest-rows').innerHTML=visible.map(g=>`<tr data-id="${escapeHTML(g.id)}"><td><div class="guest-cell"><span class="guest-initial" aria-hidden="true">${escapeHTML(g.name.split(/\s+/).map(n=>n[0]).slice(0,2).join('').toUpperCase())}</span><button class="guest-name-button" data-action="edit" title="Edit guest">${escapeHTML(g.name)}</button></div></td><td><span class="contact-line">${escapeHTML(g.phone||g.email)}</span>${g.phone&&g.email?`<span class="contact-line">${escapeHTML(g.email)}</span>`:''}<span class="channel-label">${escapeHTML(g.channel)} preferred</span></td><td><span class="badge ${g.sent?'sent':''}">${g.sent?'Marked sent':'Ready to share'}</span></td><td><div class="share-actions"><button class="icon-button" data-action="preview" title="Preview invitation" aria-label="Preview invitation for ${escapeHTML(g.name)}">${icon('eye')}</button><button class="icon-button" data-action="copy" title="Copy personal link" aria-label="Copy link for ${escapeHTML(g.name)}">${icon('link')}</button><button class="icon-button whatsapp" data-action="whatsapp" title="Open WhatsApp" aria-label="Share with ${escapeHTML(g.name)} on WhatsApp" ${!g.phone?'disabled':''}>${icon('chat')}</button><button class="icon-button" data-action="email" title="Open email" aria-label="Email ${escapeHTML(g.name)}" ${!g.email?'disabled':''}>${icon('mail')}</button><button class="icon-button" data-action="sms" title="Open SMS" aria-label="Text ${escapeHTML(g.name)}" ${!g.phone?'disabled':''}>${icon('sms')}</button></div></td><td><div class="row-menu"><input class="mark-check" type="checkbox" data-action="mark" aria-label="Mark invitation for ${escapeHTML(g.name)} as sent" title="Mark as sent after sending" ${g.sent?'checked':''}><button class="delete-button" data-action="delete" aria-label="Remove ${escapeHTML(g.name)}">${icon('trash')}</button></div></td></tr>`).join('');if(guests.length&&!visible.length)$('guest-rows').innerHTML='<tr><td colspan="5" class="no-results">No guests match your search.</td></tr>';$('showing-count').textContent=guests.length?`Showing ${visible.length} of ${guests.length} guests`:'Your list is ready for its first guest';}
function openGuest(g){editId=g?.id||null;$('guest-dialog-title').textContent=g?'Edit guest':'Add a guest';$('guest-name').value=g?.name||'';$('guest-phone').value=g?.phone||'';$('guest-email').value=g?.email||'';$('guest-channel').value=g?.channel||'whatsapp';$('guest-error').textContent='';$('guest-dialog').showModal();}
function openSettings(){$('base-url').value=settings.baseURL||(!location.hostname.endsWith('.chatgpt.site')&&!isLocal(new URL(location.href))?currentBase():'');$('settings-error').textContent='';$('settings-dialog').showModal();}
$('settings-form').addEventListener('submit',e=>{e.preventDefault();try{const url=new URL($('base-url').value.trim());if(url.protocol!=='https:'||isLocal(url)||url.username||url.password)throw new Error('Use the public HTTPS address of your deployed website.');if(url.hostname.endsWith('.chatgpt.site'))throw new Error('Use a public Vercel address. This studio preview requires sign-in.');url.hash='';url.search='';settings={baseURL:url.href};localStorage.setItem(SETTINGS_KEY,JSON.stringify(settings));$('settings-dialog').close();toast('Public invitation address saved.');}catch(err){$('settings-error').textContent=err.message;}});
$('guest-form').addEventListener('submit',e=>{e.preventDefault();try{const data=validateGuest({name:$('guest-name').value,phone:$('guest-phone').value,email:$('guest-email').value,channel:$('guest-channel').value});if(editId){const i=guests.findIndex(g=>g.id===editId);if(i>=0)guests[i]={...guests[i],...data};}else guests.push({...data,id:newId(),sent:false});const saved=persist();render();$('guest-dialog').close();if(saved)toast(editId?'Guest updated. Old links keep their original name.':'Guest added. Their invitation link is ready.');}catch(err){$('guest-error').textContent=err.message;}});
for(const id of ['add-guest','empty-add'])$(id).addEventListener('click',()=>openGuest());$('search').addEventListener('input',render);$('filter').addEventListener('change',render);$('settings-button').addEventListener('click',openSettings);document.querySelectorAll('.close-dialog').forEach(b=>b.addEventListener('click',()=>b.closest('dialog').close()));
async function copyLink(g){if(!checkSharingBase())return;const link=invitationURL(g);try{await navigator.clipboard.writeText(link);toast('Personal invitation link copied.');}catch{$('copy-link-field').value=link;$('copy-dialog').showModal();$('copy-link-field').select();}}
$('guest-rows').addEventListener('click',e=>{const button=e.target.closest('[data-action]');if(!button||button.disabled)return;const row=button.closest('tr'),g=guests.find(g=>g.id===row?.dataset.id);if(!g)return;const action=button.dataset.action;if(action==='edit')openGuest(g);else if(action==='preview')showInvitation(g.name,true);else if(action==='copy')copyLink(g);else if(action==='mark'){g.sent=button.checked;persist();render();}else if(action==='delete'){deleteId=g.id;$('delete-message').textContent=`Remove ${g.name} from this browser’s guest list?`;$('delete-dialog').showModal();}else if(['whatsapp','email','sms'].includes(action)){if(!checkSharingBase())return;const url=composeURL(g,action);if(action==='whatsapp')window.open(url,'_blank','noopener,noreferrer');else location.href=url;toast('Your sharing app is opening. Press Send there, then mark this guest as sent.');}});
$('confirm-delete').addEventListener('click',()=>{guests=guests.filter(g=>g.id!==deleteId);const saved=persist();render();$('delete-dialog').close();if(saved)toast('Guest removed.');});
function download(text,filename,type='text/csv;charset=utf-8'){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1500);}
function csvCell(value){let s=String(value??'');if(/^[=+@\-\t\r]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"';}
function parseCSV(text){text=text.replace(/^\uFEFF/,'');const rows=[];let row=[],field='',quoted=false,afterQuote=false;for(let i=0;i<text.length;i++){const c=text[i];if(quoted){if(c==='"'&&text[i+1]==='"'){field+='"';i++;}else if(c==='"'){quoted=false;afterQuote=true;}else field+=c;}else if(c==='"'){if(field.length||afterQuote)throw new Error('CSV quote is in the wrong position.');quoted=true;}else if(c===','){row.push(field);field='';afterQuote=false;}else if(c==='\n'||c==='\r'){if(c==='\r'&&text[i+1]==='\n')i++;row.push(field);if(row.some(x=>x.trim()))rows.push(row);row=[];field='';afterQuote=false;}else{if(afterQuote&&!/\s/.test(c))throw new Error('Unexpected content after a CSV quote.');if(!afterQuote)field+=c;}}if(quoted)throw new Error('CSV has an unclosed quote.');row.push(field);if(row.some(x=>x.trim()))rows.push(row);return rows;}
function decodeCell(s){s=String(s||'');return s.startsWith("'")?s.slice(1):s;}
function importGuestsCSV(text){const rows=parseCSV(text);if(rows.length<2)throw new Error('Add at least one guest row below the CSV headers.');const headers=rows[0].map(h=>h.trim().toLowerCase());if(!headers.includes('name')||(!headers.includes('phone')&&!headers.includes('email')))throw new Error('CSV headers must include name and phone or email. Optional: channel and sent.');if(rows.length>2001)throw new Error('Import up to 2,000 guests at a time.');const incoming=[];const known=new Set(guests.map(g=>`${g.name.toLowerCase()}|${g.phone}|${g.email.toLowerCase()}`));let skipped=0;for(let i=1;i<rows.length;i++){if(rows[i].length!==headers.length)throw new Error(`Row ${i+1}: the column count does not match the header.`);const raw=Object.fromEntries(headers.map((h,j)=>[h,decodeCell(rows[i][j])]));let g;try{g=validateGuest({...raw,channel:raw.channel||(raw.phone?'whatsapp':'email')});}catch(err){throw new Error(`Row ${i+1}: ${err.message}`);}const key=`${g.name.toLowerCase()}|${g.phone}|${g.email.toLowerCase()}`;if(known.has(key)){skipped++;continue;}known.add(key);incoming.push({...g,id:newId(),sent:String(raw.sent).trim().toLowerCase()==='true'});}guests.push(...incoming);const saved=persist();render();if(saved)toast(`${incoming.length} guests imported.${skipped?` ${skipped} duplicate rows skipped.`:''}`);}
$('import-csv').addEventListener('click',()=>$('csv-file').click());$('csv-file').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>2*1024*1024)throw new Error('Choose a CSV smaller than 2 MB.');importGuestsCSV(await file.text());}catch(err){toast(err.message);}e.target.value='';});
$('csv-template').addEventListener('click',()=>download('\uFEFFname,phone,email,channel,sent\r\n"Mr. & Mrs. Perera","\'+94771234567",,whatsapp,false\r\n"Nimal and Family",,guest@example.com,email,false\r\n','guest-list-template.csv'));
$('export-csv').addEventListener('click',()=>{if(!guests.length){toast('Add guests before exporting your list.');return;}const shareBase=new URL(settings.baseURL||currentBase());const publicBase=!isLocal(shareBase)&&!shareBase.hostname.endsWith('.chatgpt.site');const rows=[['name','phone','email','channel','sent','invitation_url'],...guests.map(g=>[g.name,g.phone,g.email,g.channel,g.sent,publicBase?invitationURL(g):''])];download('\uFEFF'+rows.map(row=>row.map(csvCell).join(',')).join('\r\n'),'jihani-pasindu-guest-list.csv');toast('Guest list exported. Keep this file as your backup.');});
function fitGuestName(){const el=$('card-guest');const width=el.parentElement.clientWidth;let size=Math.max(8,width*.025);el.style.fontSize=size+'px';while(el.scrollWidth>el.clientWidth+1&&size>4){size-=.25;el.style.fontSize=size+'px';}}
function resetAnimation(){animationTimers.forEach(clearTimeout);animationTimers=[];animationBusy=false;$('scroll-assembly').className='scroll-assembly';$('scroll-stage').classList.remove('expanded');$('open-invite-button').hidden=false;$('open-invite-button').disabled=false;$('open-scroll').disabled=false;$('open-scroll').setAttribute('aria-label','Untie ribbon and open invitation');$('replay-invite').hidden=true;$('opening-hint').textContent='A little something, just for you.';}
function showInvitation(name,preview=false){previewMode=preview;$('studio').hidden=true;$('guest-view').hidden=false;$('guest-greeting').textContent=`Especially for ${name}`;$('card-guest').textContent=name;$('back-studio').hidden=!preview;document.title=`For ${name} · Jihani & Pasindu`;resetAnimation();requestAnimationFrame(fitGuestName);window.scrollTo({top:0,behavior:'instant'});$('open-invite-button').focus({preventScroll:true});}
function openAnimation(){if(animationBusy)return;animationBusy=true;const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;$('open-invite-button').disabled=true;$('open-invite-button').hidden=true;$('open-scroll').disabled=true;$('scroll-assembly').classList.add('untying');$('opening-hint').textContent='A moment to remember…';const later=(fn,delay)=>animationTimers.push(setTimeout(fn,reduced?0:delay));later(()=>$('scroll-assembly').classList.add('rotating'),650);later(()=>{$('scroll-assembly').classList.add('open');$('scroll-stage').classList.add('expanded');fitGuestName();},1600);later(()=>{$('replay-invite').hidden=false;$('opening-hint').textContent='We can’t wait to celebrate with you.';animationBusy=false;$('open-scroll').setAttribute('aria-label','Opened wedding invitation');},3900);}
$('open-scroll').addEventListener('click',openAnimation);$('open-invite-button').addEventListener('click',openAnimation);$('replay-invite').addEventListener('click',()=>{resetAnimation();$('open-invite-button').focus();});
for(const id of ['sidebar-preview','preview-art','open-preview'])$(id).addEventListener('click',()=>showInvitation('Mr. & Mrs. Perera',true));function showStudio(){resetAnimation();$('guest-view').hidden=true;$('studio').hidden=false;document.title='Jihani & Pasindu · Invitation Studio';previewMode=false;render();window.scrollTo({top:0,behavior:'instant'});}
$('back-studio').addEventListener('click',showStudio);$('guests-nav').addEventListener('click',showStudio);window.addEventListener('resize',()=>{if(!$('guest-view').hidden)fitGuestName();});
function route(){if(location.hash.startsWith('#invite=')){try{const name=decodeURIComponent(location.hash.slice(8)).trim();if(!name||name.length>100)throw new Error();showInvitation(name,false);}catch{showInvitation('our dear guest',false);toast('This invitation link has an invalid name. Please ask the hosts for a new link.');}}else showStudio();}
window.addEventListener('hashchange',route);route();if(!storageOK&&$('guest-view').hidden)toast('Browser storage could not be read. Export your guest list to preserve future changes.');
